import logging
import time
from threading import Thread
from typing import List, Tuple

import zmq  # type: ignore

from taf.ul.sbts.pmi_ticket_collector.tunnel import Tunnel


class SSHWatcher:
    def __init__(self, connections: List[Tuple[Tunnel, zmq.Socket]]):
        self._logger: logging.Logger = logging.getLogger("pmi_ticket_collector.ssh_watcher")
        self._connections = connections
        self._watch_ssh_connections: bool = True
        self.ssh_broken: bool = False
        self._watcher = Thread(target=self._ssh_watcher, daemon=True)

    def start(self) -> None:
        self._watcher.start()

    def _ssh_watcher(self) -> None:
        while self._watch_ssh_connections:
            if self._connections and not all(conn[0].is_alive() for conn in self._connections):
                self.ssh_broken = True
                break
            time.sleep(5)

    def stop(self) -> None:
        self._logger.debug("Going to stop SSH Watcher")
        self._watch_ssh_connections = False
        if self._watcher.ident is None:
            return
        self._watcher.join(10)
        if self._watcher.is_alive():
            self._logger.debug("SSH Watcher is still alive")

    def is_alive(self) -> bool:
        return self._watcher.is_alive()
